// CSD_RATIONALE_BEGIN
// Diagnosis: 137/300 failures are syntax_valid but semantically wrong SQL.
// Root cause 1: Qwen3.5-4B is a THINKING model; the prior 5-step preamble gave
//   it no space to reason about query semantics before entering the constrained span.
// Root cause 2: RegenerateUnitOnGroundingFailure was rejecting valid string literals
//   ('English', 'Dutch', etc.) and operator tokens (INTERSECT) because they do not
//   literally appear in schema definitions — causing the model to fall back to simpler
//   but semantically wrong queries.
// Root cause 3: Common semantic errors observed: (a) extra columns not requested,
//   (b) OR/IN-subquery instead of INTERSECT for "A AND B on independent rows",
//   (c) repetition loops in rare cases.
//
// Fix: Replace the 5-step preamble + RegenerateUnitOnGroundingFailure with:
// 1. A 200-token thinking preamble via UnconstrainedChunk — allows Qwen3.5-4B to
//    reason about the question and schema before generating SQL.
// 2. Guidance explicitly calling out INTERSECT for independent-condition queries and
//    column-selection discipline ("only the columns asked for").
// 3. CloseSpanWithinBudget for the constrained SQL phase: dead-end-aware, tracks
//    the longest completable parse, naturally prevents repetition spirals.
// 4. UnconstrainedChunk stops as soon as "<<" appears naturally, so thinking steps
//    are not wasted when the model self-terminates the preamble early.
//
// Structure:
// Init → AppendTaskGuidance (semantic hints: INTERSECT, column discipline).
// Phase 1: UnconstrainedChunk(200) for thinking + natural "<<" detection.
// Phase 2: Force OpenConstrainedSpan if "<<" was not emitted naturally.
// Phase 3: CloseSpanWithinBudget(remaining) for parser-controlled SQL + close.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (UnconstrainedChunk): Runs only when !insideConstrainedOut, so the
//   implication is vacuous throughout Phase 1. On stoppedOnOpen == true,
//   EnterObservedConstrainedSpan sets insideConstrainedOut := true and
//   currentConstrainedOut := []. parser.IsValidPrefix([]) holds by the method
//   precondition `parser.IsValidPrefix([])`, re-establishing the invariant.
//   On stoppedOnOpen == false, insideConstrainedOut stays false, so the
//   implication remains vacuously true.
//
// Phase 2 (OpenConstrainedSpan): Runs only when !insideConstrainedOut. Its
//   postcondition sets insideConstrainedOut := true and currentConstrainedOut := [].
//   parser.IsValidPrefix([]) holds by precondition, so the invariant holds.
//
// Phase 3 (CloseSpanWithinBudget): Its postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut), directly re-establishing
//   the invariant after the call, whether the span is closed or left open.
//
// Entry with insideConstrained == true: Phases 1 and 2 are skipped entirely.
//   The precondition gives parser.IsValidPrefix(currentConstrained), initialised
//   into currentConstrainedOut. Phase 3 postcondition then preserves validity.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedChunk appends at most stepsUsed tokens to generated
//   (EOS is counted in stepsUsed but NOT appended to generated). So after Phase 1:
//   |generated| <= |generatedPrefix| + stepsUsed = |generatedPrefix| + steps.
//   EnterObservedConstrainedSpan leaves generated unchanged, preserving the bound.
//
// Phase 2: OpenConstrainedSpan appends exactly one "<<" token and steps increments
//   by 1. Net 1-for-1 growth: |generated| <= |generatedPrefix| + steps. ✓
//
// Phase 3: CloseSpanWithinBudget postcondition gives
//   |generatedOut| <= |generated_before| + closeBudget.
//   closeBudget = maxSteps − steps_before_phase3, so
//   |generatedOut| <= |generatedPrefix| + steps_before + (maxSteps − steps_before)
//                  = |generatedPrefix| + maxSteps.
//   We then set steps := maxSteps, so cost = maxSteps and the bound holds. ✓
//
// Progress postcondition (cost > 0 when maxSteps > 0):
//   If maxSteps > 0 and we enter outside the span, Phase 1 runs with
//   preambleBudget >= 1, so stepsUsed >= 1, giving cost >= 1 > 0. ✓
//   If maxSteps > 0 and we enter inside the span (Phases 1/2 skipped), Phase 3
//   runs and sets steps := maxSteps >= 1, so cost = maxSteps > 0. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Think step by step about what SQL answers the question and why. Then output exactly: SQL: <<your_query>>. Critical rules: (1) SELECT only the exact columns explicitly asked for in the question — do not add extra columns. (2) Use INTERSECT (not IN or OR) when the question asks for items satisfying two independent conditions separately, e.g. 'nations that use English AND Dutch', 'both Master and Bachelor students'. (3) Use only the exact table and column names from the provided schema.");

var steps: nat := 0;

// Phase 1: Unconstrained thinking preamble — let the model reason before SQL.
// UnconstrainedChunk stops early if "<<" appears naturally.
if !insideConstrainedOut && maxSteps > 0 {
  var preambleBudget: nat := if maxSteps >= 200 then 200 else maxSteps;
  var genOut, stoppedOnOpen, stoppedOnEos, stepsUsed :=
    helpers.UnconstrainedChunk(lm, prompt, generated, preambleBudget, "<<", eosToken);
  generated := genOut;
  steps := steps + stepsUsed;
  if stoppedOnOpen {
    // "<<" already in generated; enter constrained mode without appending another delimiter
    var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;
  }
}

// Phase 2: Force open the constrained span if the model did not emit "<<" naturally.
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Parser-controlled SQL generation and span closure within the remaining budget.
// CloseSpanWithinBudget is dead-end-aware and tracks the longest completable parse,
// preventing repetition spirals while maximising SQL quality.
if insideConstrainedOut && steps < maxSteps {
  var closeBudget: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

